{
  "dashboard": {
    "title": "Kubernetes升级状态监控",
    "panels": [
      {
        "title": "升级进度",
        "type": "gauge",
        "targets": [
          {
            "expr": "upgrade_progress_percentage",
            "legendFormat": "升级进度"
          }
        ]
      },
      {
        "title": "组件状态",
        "type": "stat",
        "targets": [
          {
            "expr": "count(kube_pod_status_ready{condition="true",namespace="kube-system"}) by (pod)",
            "legendFormat": "{{pod}}"
          }
        ]
      },
      {
        "title": "升级事件时间线",
        "type": "timeline",
        "targets": [
          {
            "expr": "upgrade_events",
            "legendFormat": "{{event}}"
          }
        ]
      }
    ]
  }
}
